    /**
     * @param int $customer
     * @param int $websiteId
     * @param array $params
     * @return bool
     */
    public function isSatisfiedBy($customer, $websiteId, $params)
    {
        if (!$customer) {
            return false;
        }
        $customerSelect = $this->getResource()->createSelect();
        $table = $this->getResource()->getTable('customer_entity');
        $customerSelect->from(['root' => $table], ['entity_id']);
        $select = $this->getConditionsSql($customer, $websiteId);
        $customerSelect->where($select);
        $matchedParams = $this->matchParameters($select, $params);
        $result = $this->getResource()->getConnection()->fetchOne($customerSelect, $matchedParams);
        return $result > 0;
    }
}
    /**
     * Check if customer is matched by segment
     *
     * @param int|\Magento\Customer\Model\Customer|\Magento\Framework\DataObject $customer
     * @param null|\Magento\Store\Model\Website|bool|int|string $website
     *
     * @return bool
     * @SuppressWarnings(PHPMD.CyclomaticComplexity)
     * @SuppressWarnings(PHPMD.NPathComplexity)
     */
    public function validateCustomer($customer, $website)
    {
        $websiteId = $this->_storeManager->getWebsite($website)->getId();
        /**
         * Use prepared in beforeSave sql
         */
        $sql = $this->getConditionSql();
        if (!$sql) {
            return false;
        }
        if ($customer instanceof \Magento\Customer\Model\Customer) {
            $customerId = $customer->getId();
        } else {
            $customerId = $customer;
        }

        $params = [];
        if (strpos($sql, ':customer_id') !== false) {
            $params['customer_id'] = $customerId;
        }
        if (strpos($sql, ':website_id') !== false) {
            $params['website_id'] = $websiteId;
        }
        if (strpos($sql, ':quote_id') !== false) {
            if (!$customerId) {
                $params['quote_id'] = $this->getQuoteId();
            } else {
                $params['quote_id'] = 0;
            }
        }
        if (strpos($sql, ':visitor_id') !== false) {
            if (!$customerId) {
                $params['visitor_id'] = $this->getVisitorId();
            } else {
                $params['visitor_id'] = 0;
            }
        }

        return $this->getConditions()->isSatisfiedBy($customerId, $websiteId, $params);
    }

