$segment = $objectManager->create(CustomerSegment::class);
$segment->load('Customer Segment Multi-Website', 'name');
$mainWebsite = $objectManager->create(WebsiteRepository::class)->get('base');
$secondWebsite = $objectManager->create(WebsiteRepository::class)->get('secondwebsite');

/** @var Collection $groupCollection */
$groupCollection = $objectManager->get(Collection::class);

/** @var Rule $salesRule */
$salesRule = $objectManager->create(Rule::class);
$salesRule->setData(
    [
        'name' => '20% Off on orders with customer segment!',
        'is_active' => 1,
        'customer_group_ids' => $groupCollection->getAllIds(),
        'coupon_type' => Rule::COUPON_TYPE_NO_COUPON,
        'simple_action' => 'by_percent',
        'discount_amount' => 20,
        'discount_step' => 0,
        'stop_rules_processing' => 1,
        'website_ids' => [$mainWebsite->getId(), $secondWebsite->getId()],
    ]
);
$conditions = [
    'type' => Combine::class,
    'aggregator' => 'all',
    'value' => 1,
    'new_child' => '',
    'conditions' => [
        [
            'type' => Segment::class,
            'operator' => '==',
            'value' => $segment->getId(),
        ],
    ],
];

$salesRule->getConditions()->loadArray($conditions);

$salesRule->save();

    /**
     * Get customer segment ids by customer id, if customer id is null return segments for visitor
     *
     * @param int|null $customerId
     * @param int $websiteId
     * @return array
     */
    public function getCustomerSegmentIdsByCustomerId(?int $customerId, int $websiteId): array
    {
        return $this->getCustomerSegmentIdsByCustomerIdQuoteId($customerId, $websiteId, 0);
    }

    /**
     * Get customer segment ids by customer id, if customer id is null return segments for visitor and quote id
     *
     * @param int|null $customerId
     * @param int $websiteId
     * @param int $quoteId
     * @return array
     */
    public function getCustomerSegmentIdsByCustomerIdQuoteId(?int $customerId, int $websiteId, int $quoteId): array
    {
        $cacheKey = $this->segmentsCache->getCacheKey($customerId, $websiteId, $quoteId);
        $cachedIds = $this->segmentsCache->load($cacheKey);

        if ($cachedIds !== false) {
            return $cachedIds;
        }

        $collection = $this->collectionFactory->create();
        $collection->addIsActiveFilter(1);
        $collection->addWebsiteFilter($websiteId);

        $customerSegmentIds = [];
        $tags = []; // Collect tags for cache invalidation

        if ($customerId) {
            $tags[] = $this->segmentsCache->getCustomerTag($customerId);
            $validated = $this->quoteMatcher->getResults($customerId, $websiteId);
            $collection->addFieldToFilter(
                'apply_to',
                [Segment::APPLY_TO_REGISTERED, Segment::APPLY_TO_VISITORS_AND_REGISTERED]
            );
            foreach ($collection as $segment) {
                $matched = $validated[(int) $segment->getId()]
                    ?? $segment->validateCustomer($customerId, $websiteId);
                if ($matched) {
                    $customerSegmentIds[] = $segment->getId();
                    $tags[] = 'SEGMENT_' . $segment->getId();
                }
            }
        } else {
            $collection->addFieldToFilter(
                'apply_to',
                [Segment::APPLY_TO_VISITORS, Segment::APPLY_TO_VISITORS_AND_REGISTERED]
            );
            foreach ($collection as $segment) {
